import math

def solve(n):
    def check(n):
        return n % 3 == 0

    def find_first(n):
        for i in range(1, n + 1):
            if check(i) and check(n - i):
                return i

    def find_last(n):
        for i in range(n - 1, 0, -1):
            if check(i) and check(n - i):
                return i

    if find_first(n) > find_last(n):
        print("First")
    else:
        print("Second")

