    time = 0
    while queue:
        time += 1
        if queue[0][0] == 0:
            return time
        cost = queue[0][0]
        dist, x, y, k = queue[0][1], queue[0][2], queue[0][3], queue[0][4]
        if dist == 0 and y < x:
            heapq.heappop(queue)
        elif dist == 0:
            heapq.heappop(queue)
            k -= 1
            if k < 0:
                heapq.heappop(queue)
            time += 1
        elif dist > 0:
            cost += 1
            heapq.heappop(queue)
            time += 1
            if k < 0:
                heapq.heappop(queue)
            dist -= 1
        elif dist == 1:
            heapq.heappop(queue)
            time += 1
        elif dist == 2:
            heapq.heappop(queue)
            time += 1
            if k < 0:
