import sys
import math
from collections import deque

def solve(x, y, k):
    if x == y:
        return 0
    if k == 0:
        return math.inf
    ans = math.inf
    if y > x:
        ans = min(ans, x + solve(x + 1, y, k - 1))
    if x < y:
        ans = min(ans, y + solve(x + 1, y, k))
    return ans

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        x, y, k = map(int, sys.stdin.readline().split())
        print(solve(x, y, k))

