        b[a[i]].append(i + 1)
        c[a[i]].append(i + 1)

    q = []
    for i in b:
        if len(b[i]) == 1:
            heapq.heappush(q, -i)
        else:
            heapq.heappush(q, (i, len(b[i])))
    ans = [-1, -1, -1]
    while q:
        u, i = heapq.heappop(q)
        if c[u] and len(c[u]) > 0:
            if u in c[u]:
                c[u].pop()
                if len(c[u]) == 0:
                    heapq.heappop(q)
            else:
                heapq.heappop(q)
                ans = [-1, -1, -1]
                break
        else:
            for j in b[u]:
                if b[j] and len(b[j]) > 0:
                    if c[j] and len(c[j]) > 0:
                        if j in c[j]:
                            c[j].pop()
                            if len(c[j]) == 0:
                                heapq.heappop(q)
                        else:
                            heapq.heappop(q)
                            ans = [-1, -1, -1]
