def solve_board(board):
    n = len(board)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    for row in range(n):
        for col in range(n):
            if board[row][col] == '+':
                for dr, dc in directions:
                    for i in range(3):
                        nr, nc = row + dr, col + dc
                        if 0 <= nr < n and 0 <= nc < n and board[nr][nc] == '.':
                            board[nr][nc] = '+'
                            if is_won(board, nr, nc):
                                return board
                            board[nr][nc] = '.'
    return board

def is_won(board, row, col):
    n = len(board)
    for i in range(n):
        if board[row][i] == board[row][col] and board[row][i]!= '.':
            return True
        if board[i][col] == board[row][col] and board[i][col]!= '.':
            return True
    if row + col < n:
        if board[row][col] == board[row + col] and board[row][col]!= '.':
            return True
    return False

if __name__ == "__main__":
