from collections import deque

def solve():
    n, m = map(int, input().split())
    x1, y1, x2, y2 = map(int, input().split())
    q = deque([(x1, y1, 0)])
    q.append((x2, y2, 0))
    visited = set()
    while q:
        x, y, dist = q.popleft()
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if x == x1 and y == y1:
            return dist
        if x == x2 and y == y2:
            return dist
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= m and (nx, ny) not in visited:
                q.append((nx, ny, dist + 1))
    return -1

